const RESPIRO = {
  compound: 'Inspira profondamente e contrai l’addome prima della fase più difficile (con carichi alti puoi trattenere il fiato 1–2 secondi: manovra di Valsalva). Espira superato il punto più duro della salita.',
  isolation: 'Inspira nella fase eccentrica (quando il muscolo si allunga), espira nella fase concentrica (quando si accorcia e solleva il peso).',
  core: 'Respira corto e continuo senza mai perdere la tensione dell’addome: non trattenere il fiato a lungo.'
};
const GLOSSARIO = [
  ['Fase eccentrica', 'la parte in cui il muscolo si allunga sotto carico, di solito la discesa. Va controllata: 2–3 secondi.'],
  ['Fase concentrica', 'la parte in cui il muscolo si accorcia e solleva il peso.'],
  ['Scapole addotte e depresse', 'strette tra loro e portate verso il basso: danno una base stabile alle spalle.'],
  ['Schiena neutra', 'la colonna con le sue curve naturali, né arrotondata né inarcata.'],
  ['Hip hinge', 'piegamento che parte dalle anche portandole indietro, con la schiena che resta neutra.'],
  ['Estensione d’anca', 'portare le anche in avanti fino a stare dritti: è il lavoro del gluteo.'],
  ['Retroversione del bacino', 'ruotare il bacino portando il pube verso le costole, come per “chiudere” la pancia.'],
  ['Valgismo', 'ginocchio che cade verso l’interno: va evitato.'],
  ['Bracing', 'contrarre l’addome a 360° come prima di ricevere un colpo, per proteggere la schiena.']
];

function schedaTecnica(name, info) {
  const t = TECNICA[String(name).replace(EMOJI_TESTA, '')];
  const meta = findExercise(name);
  if (!t) {
    return '<div class="ex-block"><div class="ex-block-title">Come si fa</div><ol class="ex-steps">' +
      info.come.map(x => '<li>' + escapeHtml(x) + '</li>').join('') + '</ol></div>' +
      '<div class="ex-block"><div class="ex-block-title warn">Errori da evitare</div><ul class="ex-steps">' +
      info.errori.map(x => '<li>' + escapeHtml(x) + '</li>').join('') + '</ul></div>';
  }
  const tipo = meta && meta.group === 'core' ? 'core' : (meta && meta.type === 'compound' ? 'compound' : 'isolation');
  return '<div class="ex-muscoli">' + escapeHtml(t.m) + '</div>' +
    '<div class="ex-block"><div class="ex-block-title">Posizione di partenza</div><p class="ex-p">' + escapeHtml(t.s) + '</p></div>' +
    '<div class="ex-block"><div class="ex-block-title">Come si fa</div><ol class="ex-steps">' +
      t.e.map(x => '<li>' + escapeHtml(x) + '</li>').join('') + '</ol></div>' +
    '<div class="ex-block"><div class="ex-block-title">Pensa a</div><ul class="ex-steps">' + cueEsercizio(name).map(x => '<li>' + x + '</li>').join('') + '</ul></div>' +
    '<div class="ex-block"><div class="ex-block-title">Respirazione</div><p class="ex-p">' + escapeHtml(respiroPer(tipo)) + '</p></div>' +
    '<div class="ex-block"><div class="ex-block-title warn">Errori da evitare</div><ul class="ex-steps">' +
      t.x.map(x => '<li>' + escapeHtml(x) + '</li>').join('') + '</ul></div>' +
    '<div class="ex-cue"><b>Il consiglio del coach</b>' + escapeHtml(t.c) + '</div>' + preferenzaEsercizio(name);
}
/* Attrezzo, presa o attacco, focus e le altre prese dello stesso movimento */
function htmlDettaglioScheda(name) {
  const d = dettaglioEsercizio(name), m = findExercise(name);
  if (!d) return '';
  const sez = (SEZIONI_ESERCIZI.find(x => x[0] === d.sez) || ['', ''])[1];
  const varianti = variantiEsercizio(name);
  return '<div class="ex-block ex-det"><div class="ex-block-title">Attrezzo e focus</div>' +
    '<div class="res-line"><span>Dove</span><b>' + escapeHtml(sez) + '</b></div>' +
    '<div class="res-line"><span>Attrezzo</span><b>' + escapeHtml(d.att) + '</b></div>' +
    (d.attacco ? '<div class="res-line"><span>Presa o attacco</span><b>' + escapeHtml(d.attacco) + '</b></div>' : '') +
    '<div class="res-line"><span>Tipo</span><b>' + (m && m.type === 'compound' ? 'multiarticolare' : 'isolamento') + '</b></div>' +
    '<div class="res-line"><span>Focus</span><b>' + escapeHtml(d.focus) + '</b></div>' +
    (d.sec ? '<div class="res-line"><span>Secondari</span><b>' + escapeHtml(d.sec) + '</b></div>' : '') +
    (d.nota ? '<div class="ex-note-att">' + escapeHtml(d.nota) + '</div>' : '') +
    (varianti.length ? '<div class="ex-block-title ex-var-t">Altre prese e attacchi</div><div class="ex-var">' +
      varianti.map(v => '<button type="button" class="ex-var-b" onclick="openExerciseInfo(\'' + jsArg(v.name) + '\', \'come\')">' + escapeHtml(senzaEmoji(v.name)) + '</button>').join('') + '</div>' : '') +
    '</div>';
}
function pausaConsigliata(nome) { const t = tipoCarico(nome); return t === 'pesante' ? '2–3 min (forza 3–5)' : (t === 'macchina' ? '1,5–2 min' : '60–90 s'); }
function preferenzaEsercizio(name) {
  const sch = schemaDi(name), sc = sch ? SCHEMI_MOV.find(x => x[0] === sch)[2] : null;
  let h = '<div class="ex-block"><div class="ex-block-title">Per il coach</div>' +
    (sc ? '<div class="res-line"><span>Schema</span><b>' + sc + '</b></div>' : '') +
    '<div class="res-line"><span>Pausa consigliata</span><b>' + pausaConsigliata(name) + '</b></div>' +
    '<div class="res-line"><span>Ripetizioni in riserva</span><b>' + rirBersaglio(name).join('–') + '</b></div>' +
    (tipoCarico(name) === 'pesante' ? '<div class="res-line"><span>Cintura</span><b>Solo serie pesanti</b></div>' : '');
  if (coachAttivo()) {
    const p = getProfile() || {};
    const piace = (p.graditi || []).indexOf(name) !== -1, no = (p.odiati || []).indexOf(name) !== -1;
    const q = JSON.stringify(name).replace(/"/g, '&quot;');
    h += '<div class="ex-pref"><button class="ex-pref-b' + (piace ? ' on' : '') + '" aria-pressed="' + piace + '" onclick="preferisci(' + q + ', \'graditi\')">' + ico('cuore') + ' Mi piace</button>' +
      '<button class="ex-pref-b' + (no ? ' on no' : '') + '" aria-pressed="' + no + '" onclick="preferisci(' + q + ', \'odiati\')">' + ico('stop') + ' Non lo voglio</button></div>' +
      '<div class="sr-note">Il coach mette in scheda quelli che ti piacciono e sostituisce quelli che non vuoi con un equivalente.</div>';
  }
  return h + '</div>';
}
window.preferisci = function(name, lista) {
  const p = getProfile() || {};
  p.graditi = p.graditi || []; p.odiati = p.odiati || [];
  const altra = lista === 'graditi' ? 'odiati' : 'graditi';
  const i = p[lista].indexOf(name);
  if (i === -1) { p[lista].push(name); p[altra] = p[altra].filter(x => x !== name); } else p[lista].splice(i, 1);
  localStorage.setItem(PROFILE_KEY(), JSON.stringify(p));
  if (lista === 'odiati' && p.odiati.indexOf(name) !== -1) {
    const alt = sostituto(name, prefsCoach(), []);
    /* nessun esercizio dello stesso muscolo con i tuoi attrezzi: resta in scheda, e lo dico */
    if (alt) conAnnulla(senzaEmoji(name) + ' \u2192 ' + senzaEmoji(alt.name), () => sostituisciNelPiano(name, alt.name, 'Sostituito: ' + senzaEmoji(name) + ' non ti piace'));
    else if (DAYS.some(g => (loadData()[g] || []).some(e => e.name === name))) showUndo(trP('Nessun sostituto con lo stesso muscolo: %s resta nel piano', tr(senzaEmoji(name))), null, 6000);
  }
  /* il pulsante si accende subito, senza ridisegnare la scheda */
  if (exInfoNome === name && document.querySelector('.ex-pref-b')) {
    document.querySelectorAll('.ex-pref-b').forEach((b, i) => {
      const on = i === 0 ? p.graditi.indexOf(name) !== -1 : p.odiati.indexOf(name) !== -1;
      b.classList.toggle('on', on);
      if (i === 1) b.classList.toggle('no', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
      b.classList.remove('pop');
      if (on) { void b.offsetWidth; b.classList.add('pop'); }
    });
  } else openExerciseInfo(name, 'come');
};

window.openExerciseInfo = function(name, tab) {
  const meta = findExercise(name);
  const pid = patternFor(name);
  const info = PATTERN_INFO[pid] || PATTERN_INFO.machine;
  /* Lo spazio dell immagine resta riservato: qui andranno le foto o i video
     dell esercizio quando saranno pronti. Il disegno provvisorio e' stato
     tolto, ma il riquadro c e gia con le sue proporzioni, cosi il giorno
     che carichiamo le immagini nulla si sposta. */
  const disegno = slotImmagine(name);
  const gruppo = meta ? MUSCLE_GROUPS[meta.group] : null;
  const verificato = !!VIDEO_VERIFICATI[name];

  document.getElementById('ex-info-title').innerText = String(name).replace(EMOJI_TESTA, '');
  document.getElementById('ex-info-sub').innerText = (gruppo ? gruppo.label : '') +
    (meta ? ' \u2022 ' + (meta.type === 'compound' ? 'multiarticolare' : 'isolamento') : '');

  exInfoNome = name;
  const sed = seduteEsercizio(name);
  document.getElementById('ex-info-body').innerHTML =
    '<div class="ex-tabs" id="ex-tabs" role="tablist">' +
      [['come', 'Come si fa'], ['storico', 'Storico'], ['grafico', 'Grafico'], ['record', 'Record']].map(([k, l]) =>
        '<button type="button" role="tab" data-t="' + k + '" onclick="setExInfoTab(\'' + k + '\')">' + l + '</button>').join('') +
    '</div>' +
    '<div id="ex-pane-storico" class="ex-pane">' + paneStorico(sed) + '</div>' +
    '<div id="ex-pane-grafico" class="ex-pane">' + paneGrafico(sed) + '</div>' +
    '<div id="ex-pane-record" class="ex-pane">' + paneRecord(sed) + '</div>' +
    '<div id="ex-pane-come" class="ex-pane">' +
    '<div class="ex-draw-wrap">' + disegno + '</div>' +
    '<div class="ex-pattern">Schema: ' + escapeHtml(info.nome) + '</div>' +
    htmlDettaglioScheda(name) +
    schedaTecnica(name, info) +
    '<a class="ex-video" href="' + videoLinkFor(name) + '" target="_blank" rel="noopener noreferrer">\u25B6 ' +
      (verificato ? 'Guarda il video tutorial' : 'Cerca un video su YouTube') + '</a>' +
    '<div class="ex-note">' + (verificato ? 'Il video è una fonte italiana che ho verificato.' :
      'Il pulsante apre una ricerca su YouTube: non posso guardare i video, quindi preferisco non indicarti uno specifico senza averlo visto.') +
      ' Una raccolta di tutorial in italiano che ho verificato: <a href="' + VIDEO_PLAYLIST + '" target="_blank" rel="noopener noreferrer">playlist Project inVictus</a>.</div>' +
    '<details class="ex-gloss"><summary>Parole del coach</summary>' +
      GLOSSARIO.map(g => '<p><b>' + g[0] + '</b>: ' + g[1] + '</p>').join('') + '</details>' +
    '</div>';

  setExInfoTab(tab || 'come');
  document.getElementById('ex-info').classList.remove('hidden');
};

window.closeExerciseInfo = function() {
  document.getElementById('ex-info').classList.add('hidden');
};
